insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9794712','utility','9794712','US','10/17/2017','A method of decomposing a matrix of dimension L-by-N, where L is less than or equal to N, into a sequence of N-by-N unit primitive matrices and a permutation matrix comprising a sequence that is the product of the primitive matrices and the permutation matrix, containing L rows that are substantially close to the provided L-by-N matrix, where the choice of the permutation matrix and the indices of the non-trivial rows in the primitive matrices are chosen to limit the coefficient values in the primitive matrices.','Matrix decomposition for rendering adaptive audio using high definition audio codecs','B2',20,'ipg171017.xml',0,'[0.0006309612,-0.01687974,0.030608742,-0.021475649,0.042683747,0.07155878,0.007838621,-0.02364567,0.06763335,-0.014894865,-0.06275645,0.039533366,0.06349832,-0.0380017,-0.004127851,0.014317319,0.024367422,-0.058358386,-0.037075154,0.037588734,0.09416099,-0.08707968,-0.06804872,0.010154249,0.008230218,-0.051691707,-0.04655867,-0.052814983,0.005972142,0.013264175,-0.001131257,0.00816019,0.08717304,0.015552366,0.0057055796,0.027936354,-0.004657394,-0.0059322645,0.06998937,-0.01589629,0.023275396,-0.02660559,0.023546398,-0.00077709375,-0.0028943245,0.050308123,-0.014172057,0.06267979,0.04272783,-0.030177148,0.0036189868,-0.014130196,-0.013614282,0.028592648,0.057781488,-0.014433199,0.047220092,0.006108171,-0.037046235,-0.007878872,0.0015762852,-0.081441924,0.017418865,0.063572615,-0.045131173,0.052235577,-0.014192074,-0.06101846,0.026728125,0.007908351,0.02461403,-0.020501854,0.05255686,-0.019237412,0.016919123,-0.074783154,0.0063350396,-0.05449633,0.06933149,0.067540206,-0.047013715,-0.08790872,-0.013353781,0.03303168,0.062802695,0.028850064,0.03227063,-0.055593822,0.03593289,0.009147475,0.027494885,-0.027642267,0.029995715,-0.045615025,-0.012791491,-0.038609046