insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6528714','utility','6528714','US','3/4/2003','A hi-hat cymbal stand mainly having a rod for holding cymbals, a movable foot pedal located at a lower section of the rod, and a contractible tripod. One leg of the tripod may be detached for adding more equipment around the stand without interference. A sliding plate is provided to help anchor with other two legs on the floor. The depressing plate may be loosened to disengage two hooks of a bottom plate from the axis of a post plate so that the foot pedal may be turned and leaned on the rod to facilitate storing and carrying.','Hi-hat cymbal stand','B1',2,'pg030304.zip',0,'[-0.0070159896,-0.012034615,0.0067684883,-0.034655903,-0.03390938,0.06345068,0.036206193,-0.048776314,0.036026068,-0.05023147,-0.02833606,0.025551023,0.07117178,-0.059467025,0.016871694,0.019324366,0.034688827,-0.056761324,0.032053187,-0.054479133,0.02956498,-0.06807469,-0.0241534,-0.013357856,0.035456978,-0.062084273,0.030469578,0.011389082,-0.05527739,0.07972501,0.0016320819,-0.011170681,-0.003065026,-0.042936474,-0.0075807124,-0.034029108,0.0115293935,0.051898077,0.022232708,0.027735429,0.020605465,-0.105919816,0.017609045,-0.053012963,0.0037211955,0.045199137,0.005838067,0.026076922,-0.0045981323,-0.06555698,0.044973467,0.06575889,0.05216479,-0.020994341,0.032194685,0.06692452,0.02876209,0.043569,-0.024871996,-0.00064219086,0.041199114,-0.081480555,0.00041831465,0.014749698,0.008911925,0.069975525,-0.017569382,0.019821715,0.014527525,-0.018049033,0.03370398,-0.052557725,0.025248684,-0.034411944,-0.005902681,0.010269052,0.0032471928,0.013665484,-0.033550866,0.03805896,-0.050593946,-0.0027804426,-0.071265884,-0.020561704,-0.031052817,-0.07292787,0.006992289,0.022096446,0.02742638,-0.009366689,-0.034646332,0.019645385,-0.0074740387,0.022879485,0.0063262973,0.03526958,0.011187138,0.074059926,-0.017626708,0.04817