insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9802857','utility','9802857','US','10/31/2017','Substantially alkali free glasses are disclosed with can be used to produce substrates for flat panel display devices, e.g., active-matrix liquid crystal displays (AMLCDs). The glasses have high annealing temperatures and etch rates. Methods for producing substantially alkali free glasses using a downdraw process (e.g., a fusion process) are also disclosed.','Dimensionally stable fast etching glasses','B2',12,'ipg171031.xml',0,'[0.010184932,-0.0787374,0.010205748,-0.01509792,-0.03690239,0.0015492463,-0.017258978,0.028941955,0.032237224,-0.028552545,-0.011714702,-0.027742034,-0.0015047789,-0.09739286,0.025868848,-0.048733614,0.03612776,-0.047536068,0.027274735,0.053180218,0.036351647,-0.11918528,-0.030912558,0.010355324,0.01031957,-0.09080034,-0.015400601,0.00966246,-0.02433571,0.07269036,0.09895807,-0.01527466,0.05167675,-0.003446958,-0.0017451762,-0.03760282,0.054822918,-0.012186863,-0.0022997402,-0.015584769,0.09225371,-0.05055713,0.0077641434,-0.020277422,0.0025628875,0.023354558,-0.012812372,0.031196833,0.0091343215,-0.037372813,0.015290678,0.048239525,-0.02392123,-0.0350189,0.042403463,-0.0076209074,0.02631558,0.03843399,-0.012205837,-0.0018756165,-0.016153742,-0.00035242017,-0.016681897,-0.00397492,-0.040026996,0.0047555026,0.03483813,0.01374106,-0.009801845,-0.027279837,-0.038670562,-0.0119382255,0.079700746,-0.0016382731,-0.0030275725,-0.069217466,0.0379724,0.034020793,0.021692978,0.04653541,-0.090026796,-0.06988386,0.028174289,0.023484332,0.0004276565,-0.03870864,-0.03529879,-0.03792404,-0.036313407,0.09507336,0.035140567,-0.042501174,0.047086906,-0.026489677,0.030345095,0.02469766,-0.006462956,-0.00064473663,0.052089367,0.02846905,-0.002717868,0.034984715,0.0013803004,-0.034768254,0.013228381,0.10539636,-0.017939687,0.007883794,0.012854607,-0.022328582,0.004519317,-0.06