insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8470172','utility','8470172','US','6/25/2013','A system for enhancing an activated sludge process including at least one biological reactor. A weighting agent impregnation subsystem is coupled to the biological reactor for mixing biological flocs and weighting agent to impregnate the weighting agent into the biological flocs to form weighted biological flocs. A weighting agent recovery subsystem is configured to recover the weighting agent from the weighted biological flocs and reintroducing the recovered weighting agent to the weighting agent impregnation subsystem.','System for enhancing a wastewater treatment process','B2',29,'ipg130625.xml',0,'[-0.010139418,0.02205121,0.0016493966,-0.009623185,0.06419676,0.013373911,-0.009277209,0.06814592,0.016305441,0.025713615,-0.027601158,-0.0655272,0.003513871,-0.053024996,0.06407654,0.007088877,0.037762973,-0.06603221,0.023145527,0.02419981,0.007188284,-0.06019723,-0.039996766,0.06172812,0.0376768,-0.08701726,-0.00900343,-0.0392345,-0.06045793,0.017471915,0.036386043,-0.025923919,0.044278145,-0.024633605,-0.021367546,-0.01987403,0.055555318,0.0055158054,0.044712476,-0.0008246289,0.021521905,-0.038266454,0.035680406,-0.022466162,-0.03528113,0.012204715,0.016512088,-0.007733722,0.076662414,-0.03180847,0.043829117,0.022367084,0.013593983,0.010887629,0.06955017,0.05238592,0.03759613,-0.017234067,0.006908673,0.028106172,-0.01223857,-0.050467778,0.012385395,0.023161817,-0.0076486375,0.08985904,0.06571931,0.057093844,0.025435638,-0.06484208,0.009227525,-0.052581426,0.062397502,-0.07635634,-0.045570374,-0.031117601,-0.01632699,0.040995587,-0.010600594,0.035659265,0.010163003,-0.06655118,-0.039557356,-0.006491502,-0.00012795709,-0.04102152,-0.049057532,-0.046652637,-0.0049890094,0.06059897,-0.043118414,-0.008974036,0.07319018,-0.033076786,-0.000333519,0.08420116,-0.0052228025,0.08195591,-0.03