insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9804061','utility','9804061','US','10/31/2017','A method for testing water droplet shedding ability of a surface of an aircraft wing includes: blowing air toward a surface of a cylindrical member in an airflow direction perpendicular to an axial direction of the cylindrical member, the cylindrical member simulating the wing and having water-related surface characteristics that differ across a predetermined boundary position in a circumferential direction; supplying a water droplet to a portion of the surface of the cylindrical member on a leading edge side with respect to a flow of the air; and capturing an image of the water droplet that moves on the surface of the cylindrical member across the boundary position due to the flow of the air.','Method and device for testing water droplet shedding ability of aircraft wing','B2',15,'ipg171031.xml',0,'[-0.030231211,0.006999622,0.039397743,-0.016129732,-0.023558034,0.04796064,-0.02303868,0.004780759,0.015753161,-0.05544682,0.018352726,-0.01986492,0.043683764,-0.020234969,0.05554025,0.018302126,0.048959684,-0.05961596,-0.07460745,-0.027030608,0.0076484773,-0.03939329,-0.01737864,0.024129482,0.017037446,-0.06635114,0.021964736,-0.079477474,-0.047406454,0.026132511,-0.029002585,-0.031369675,0.0012219986,-0.010619296,0.03327894,-0.020801688,0.021504693,0.01402685,0.013261914,0.033644605,0.0548317,-0.053315848,-0.0010753035,-0.050396044,-0.04994495,0.017026966,-0.020345869,0.0034435075,0.03261112,-0.08857204,-0.0026043537,0.030422464,0.0013501593,-0.020847978,0.03560531,0.046715856,0.004054771,0.09944952,-0.029832894,-0.037392456,0.03180208,-0.0041539026,0.03041594,0.0018648853,-0.09835539,0.017679762,0.0010825918,0.00946853,0.019102432,-0.05884551,-0.032111518,-0.011111233,-0.0027549206,0.015982747,-0.017621849,-0.049447097,-0.0063475366,-0.02371446,-0.02581301,0.0693277,-0.040704478,0.