insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9804075','utility','9804075','US','10/31/2017','The present disclosure provides a particle sorting apparatus, a particle sorting method, and a non-transitory computer-readable storage medium storing program that enable sorting object particles to be sorted with high precision, even when the sorting object particles are large. In the particle sorting apparatus, a charging unit that applies charges to at least a part of liquid droplets ejected from an orifice to generate a fluid stream and a charging control unit that adjusts a charge application end time in the charging unit according to sizes of particles included in the liquid droplets are provided.','Particle sorting apparatus, particle sorting method, and non-transitory computer-readable storage medium storing program','B2',12,'ipg171031.xml',0,'[-0.014118968,0.006421092,0.01858435,-0.019976474,0.011299609,0.12566668,0.0032459013,0.05637851,0.031834915,0.015717266,0.0055966233,-0.016269844,0.03109992,-0.050895978,0.022123614,-0.0015619827,0.023068914,-0.10648645,-0.018592762,0.0063307527,0.010102064,-0.017401727,-0.007771321,0.020907275,0.026659444,-0.06976251,-0.005165468,-0.023534507,-0.05095365,0.0506109,0.01582482,0.0014617378,0.048519496,-0.036242463,0.019818693,-0.017606007,0.031860057,-0.011239643,0.059124354,-0.0014595356,0.042793382,-0.08018087,0.030725902,0.023121005,-0.026184443,-0.003270425,-0.015175522,0.013306663,0.04507291,-0.088545315,-0.05457467,-0.007712954,0.004376816,-0.034617234,0.041130368,-0.010413034,0.010707041,0.04766846,0.027072474,0.059506822,-0.06388797,-0.0682028,0.015948955,0.025503552,-0.06707701,0.044119895,0.04865801,-0.0002829767,-0.0063478,-0.0696773,-0.03588363,0.00054282206,0.011066172,-0.025163453,0.0025878516,-0.079983644,-0.028704813,0.031645432,-0.005066529,0.092022635,-0.04146012,-0.014489525,-0.0606679,0.03953943,0.052970238,0.026