insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9805184','utility','9805184','US','10/31/2017','A method of unlocking an electronic device based on motion recognitions generates motion information by detecting a users motion, calculates optical flows based on the motion information, converts the optical flows into a code by sorting and grouping the optical flows based on predetermined reference directions, generates a comparison result indicating whether the code is consistent with a predetermined password by comparing the code with the predetermined password, and determines whether to unlock the electronic device based on the comparison result.','Method of unlocking an electronic device based on motion recognitions, motion recognition unlocking system, and electronic device including the same','B2',14,'ipg171031.xml',0,'[-0.032333672,-0.056613952,-0.0102076195,-0.02803825,0.01180059,0.053334586,0.02931058,0.029198566,0.009395583,-0.05806604,0.014832543,0.023194663,0.05853537,-0.048869137,0.08309484,0.010052186,0.044037536,-0.066103145,-0.019043561,-0.033001587,0.031276956,-0.018096592,-0.015184466,0.05184475,0.01593111,-0.057602216,0.0012611384,-0.0327202,-0.05703267,0.057926957,0.0197276,-0.038596865,0.032141842,0.0365352,0.041919027,-0.06775138,0.02330228,0.020816306,0.032123554,-0.06587494,0.03693949,-0.014065944,0.005486814,-0.04937849,-0.008858536,0.05040566,0.019896343,-0.02713153,-0.0025025564,-0.086771235,-0.034057166,0.010334816,0.028328978,0.00071389426,-0.015648715,0.027215997,-0.00972921,0.030731268,-0.025034111,-0.017669376,0.013472375,0.02000009,0.03509556,0.04500691,-0.08666784,0.058755863,0.01905789,-0.0139715,0.041706283,-0.042921156,0.020965664,-0.019494483,0.025336629,-0.039532963,-0.011948496,-0.022313984,0.029624805,-0.0003020548,-0.042867333,0.014685879,-0.06888016,-0.046917073,-0.046249684,0.037645295,0.029821852,-0.034814782,0.036379132,0.03852152,0