insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9806142','utility','9806142','US','10/31/2017','A display device comprising: a substrate with a display region and a border region; a first metal layer disposed on the substrate; a first insulating layer disposed on the first metal layer and having a first contact via on the border region; a second metal layer disposed on the first insulating layer and in the first contact via to electrically connect to the first metal layer; a second insulating layer disposed on the second metal layer; a first electrode layer disposed on the second insulating layer and having a first opening; a third insulating layer disposed on the first electrode layer and has a second opening on the border region; and a second electrode layer disposed on the third insulating layer and in the second opening to electrically connect to the first electrode layer, wherein the first contact via corresponds to the first opening, is disclosed.','Display device','B2',10,'ipg171031.xml',0,'[0.0022182635,-0.02623252,0.045053206,-0.02328157,-0.038022485,0.0013472071,-0.0137220165,-0.02785993,0.02847359,-0.023072215,-0.023295883,0.004862272,0.03959671,-0.06296038,0.00483608,-0.036855493,0.040128652,-0.046508946,0.011704812,-0.03801928,-0.023212217,-0.07563267,-0.06241332,0.01231069,0.0746273,-0.09506609,-0.009859414,-0.0094802,-0.036145676,0.06905058,0.030832646,-0.012978244,0.00717761,0.020904593,-0.013265641,-0.01554855,0.038981035,0.011579592,0.033599645,-0.009249679,0.08520657,-0.025868786,-0.0062789647,-0.02816657,-0.0279372,0.035732515,-0.049141265,0.046090957,0.015035135,-0.019919282,0.016389301,0.07001978,-0.019592492,-0.03922648,0.013582996,0.015028007,0.035407826,0.05057185,0.010790653,-0.009804406,-0.03272236,0.004425392,-0.0040057367,0.027256817,-0.07054488,0.01563231,0.027237475,0.01942707,0.023275657,-0.010289534,-0.022583473,-0.037204433,0.048739407,-0.0