insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9817812','utility','9817812','US','11/14/2017','Systems and methods for identifying word collocations in natural language texts. An example method comprises: performing, by a computing device, semantico-syntactic analysis of a natural language text to produce a plurality of semantic structures; generating, in view of relationships defined by the semantic structures, a raw list of word combinations; producing a list of collocations by applying a heuristic filter to the raw list of word combinations; and using the list of collocations to perform a natural language processing operation.','Identifying word collocations in natural language texts','B2',20,'ipg171114.xml',0,'[0.00068860064,-0.01066876,-0.047642432,-0.011329137,0.026152326,0.078625634,-0.008369907,0.00092029123,0.013407996,-0.0041583297,-0.048698947,0.011375623,0.094992936,-0.0669741,0.018520985,0.009535567,0.081376545,-0.064075254,0.011956808,-0.016799916,0.06439743,-0.041669596,-0.027148444,0.013649016,0.081735805,-0.06533763,-0.017499054,-0.0352393,-0.02921952,0.017519347,0.041405804,0.030661002,0.0671896,-0.0006265368,0.0354427,0.016135918,0.030993342,0.056557238,0.0892596,0.026779553,0.044208862,-0.022343203,-0.0061328155,-0.025417482,-0.0250326,0.073249154,-0.022489348,-0.038230985,0.0027450777,-0.042872123,0.022625946,0.0020780398,0.013113741,0.07577494,0.12479428,0.03503906,0.0009248105,0.0073177344,-0.003082246,-0.01155359,-0.0022187624,-0.057876475,0.053083267,-0.028945003,-0.057616144,0.09030818,-0.011015391,-0.019689443,-0.038286984,-0.015994046,0.0074712755,-0.0011417338,0.041235577,0.0070962654,-0.051380627,-0.10737727,0.026146451,0.03373033,-0.013417521,0.042607352,-0.06587964,-0.105172016,0.00636653,0.052611645,0.0609332,-0.018627001,0.016718289,-0.024179995,0.012665639,0.01229959,0.013594465,0.005289678,0.047651272,-0.033576135,0.083113894,0.04019245,