insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9818940','utility','9818940','US','11/14/2017','A method for fabricating an Organic Light-Emitting Diode (OLED) display panel is provided. The method includes arranging Thin-Film Transistor (TFT) devices on one side of a substrate and a function layer on the other side of the substrate to form a laminate including both the TFT devices and the function layer, attaching the laminate onto a loading platform such that the function layer included in the laminate faces towards the loading platform, and conducting a process on the laminate to form an organic electroluminescent material layer on surfaces of the TFT devices.','Large-sized AMOLED display substrate and manufacturing method thereof','B2',17,'ipg171114.xml',0,'[0.0041317637,-0.017244482,0.032950506,-0.026794152,-0.026243173,0.015260497,-0.081301056,0.004381305,0.007831493,0.021578014,-0.027374914,-0.026929218,0.014639302,-0.033649873,0.057506997,-0.012737537,0.07347176,-0.053127326,0.02259653,-0.013541116,-0.0003633793,-0.048932243,-0.055830583,0.02992626,0.0368195,-0.10130041,-0.034563597,-0.04101139,-0.070470944,0.077208176,0.07470294,-0.047823228,0.008366246,-0.01068648,-0.0011568981,-0.038338773,0.07713214,0.00096609315,0.0052476614,0.028014353,0.09996919,-0.006429397,0.01856632,-0.016070519,-0.057157133,0.018852388,-0.0138456235,0.048143186,0.04044297,0.019334124,0.008278438,0.066055275,-0.019784462,-0.023629203,0.0208322,0.019675298,0.015468163,0.04266893,0.0022742029,-0.005263719,-0.008431338,0.02768085,-0.008947283,0.010803373,-0.044773273,0.022178749,0.016761517,-0.009478918,-0.031454377,-0.033471636,-0.008970014,-0.009841458,0.030626329,-0.08311894,-0.028601512,-0.044275407,0.029547166,-0.02827457,-0.027254805,0.1144908,-0.018397687,-0.03149611,-0.03408355,-0.014596993,-0.013600595,-0.021490864,0.042639066,-0.032517288,-0.02030057,0.056923755,0.018111542,-0.04139