insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8468442','utility','8468442','US','6/18/2013','A method of viewing information associated with data in a spreadsheet, includes providing a document including data and information associated with the data, parsing the document to retrieve the associated information, processing the associated information to break the associated information down into at least one sentence, categorizing the at least one sentence to determine whether the at least one sentence corresponds to at least one category in a taxonomy corresponding to the data, assigning an association strength to the categorized at least one sentence, the association strength indicating a likelihood that the categorized at least one sentence actually corresponds to the at least one category in the taxonomy, filtering the at least one categorized sentence based on the association strength to determine whether to match the categorized at least one sentence with the at least one category in the taxonomy and outputting only the categorized at least one sentence matched with the at least one category in the taxonomy.','System and method for rendering data','B2',20,'ipg130618.xml',0,'[-0.014538318,0.0036804269,0.0049954,-0.0016232096,-0.0028511349,0.04612238,0.021233572,-0.018960211,-0.0033657826,0.018652027,-0.07147385,0.05568743,0.07733775,-0.07423445,0.039776407,0.05197633,0.053383812,-0.03221875,0.012744226,-0.00880998,0.038648993,-0.049577706,-0.07237138,0.004406383,0.0427836,-0.037620384,-0.057512585,-0.010925615,-0.016462235,0.028189957,0.022841811,0.002426832,0.030730268,-0.011445073,0.023472436,0.045877818,0.016157536,-0.006700266,0.06552228,-0.061992865,0.042912886,-0.0015471281,0.0072321407,-0.011111458,-0.002053689,0.028639548,-0.017915452,-0.03320735,-0.004135499,-0.054948233,0.013370947,0.022106308,0.009818763,0.04578565,0.06852461,0.029087858,0.047724366,-0.029235