insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8470636','utility','8470636','US','6/25/2013','The present invention relates to aqueous processes to make metal chalcogenide nanoparticles that are useful precursors to copper zinc tin sulfide/selenide and copper tin sulfide/selenide. In addition, this invention provides processes for preparing crystalline particles from the metal chalcogenide nanoparticles, as well as processes for preparing inks from both the metal chalcogenide nanoparticles and the crystalline particles.','Aqueous process for producing crystalline copper chalcogenide nanoparticles, the nanoparticles so-produced, and inks and coated substrates incorporating the nanoparticles','B2',10,'ipg130625.xml',0,'[-0.0063647507,-0.0125581985,0.015354498,-0.04503454,0.040904798,0.04652546,-0.044652946,0.012751907,0.03685596,-0.028193036,-0.0038176607,0.022114802,0.026667332,-0.04361936,0.025512455,0.023725098,0.063234635,-0.06342752,0.0047491575,0.020716941,0.0367902,-0.033994135,0.036010027,0.03176002,-0.0040251855,-0.07626373,-0.04171943,0.035918534,-0.02077417,0.04973261,0.01795528,-0.0070099495,0.061981283,-0.01156045,0.04810329,-0.035825964,0.01720851,-0.008636197,0.025081899,0.0011921248,0.073666885,-0.05720403,-0.013750867,-0.014603243,0.0077012023,0.024237128,-0.029597418,0.09049543,0.015204373,0.010523846,0.05397977,0.059182893,-0.024286248,-0.037484013,-0.004659666,-0.021430558,0.04919418,0.08995679,-0.016359143,0.012606068,-0.017155778,-0.10901467,0.015331683,-0.017880397,-0.021087231,0.007458814,0.10109964,0.040655296,0.008105736,0.01224456,-0.01895709,-0.015791334,-0.023959177,-0.00913148,0.00487051,-0.06382044,-0.01652555,0.010417512,0.011539227,0.062443435,-0.01915179,-0.0513366,-0.039733075,0.017869195,-0.0012692839,-0.026744623,-0.043545734,-0.025642164,0.007951501,0.031508513,-0.03872963,-0.023347404,0.046314042,0.009571804,0.014381802,-0.006651802,0.0