insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8473841','utility','8473841','US','6/25/2013','A system and a method are disclosed for a configuration in which any user interface feature that would otherwise have been hidden while the user is interacting with the rest of the web page are made available at the top of the web page. If the user scrolls up to the top of the page the bar will disappear again to make the entire browser window available for page content and not conflict with the top user interface elements.','Independent visual element configuration','B2',12,'ipg130625.xml',0,'[-0.03992338,-0.043413997,0.03651201,-0.0018170535,-0.0027158405,0.046527676,-0.018846365,-0.04360822,0.02309058,-0.03795559,-0.11053063,0.04355753,0.09960239,-0.0461279,0.036123853,0.029365389,0.014055387,-0.033671737,0.008476484,-0.020234684,0.0031938157,-0.0539667,-0.03900554,0.01683673,0.027732622,-0.09782207,-0.007107592,-0.019265378,-0.10446677,0.09432746,0.054833677,0.02210727,0.028260449,0.0016280968,-0.015584311,-0.0026123347,0.043228682,-0.016343705,-0.00935938,-0.012931083,0.065983266,-0.018541923,-0.0016710508,-0.0830411,-0.029296871,0.06775089,-0.047059037,0.022814635,0.046061084,-0.08265553,-0.022208579,0.08123176,0.043888856,-0.04040907,-0.028740387,-0.007201754,0.019392498,0.027498309,-0.025446502,-0.003462534,-0.05196308,0.0030272896,0.007951289,-0.03202045,-0.08966921,0.04965001,0.026099185,0.0013726942,0.028376859,-0.029387986,0.021720791,-0.05386654,0.062067907,-0.053754315,0.03849142,-0.009537416,0.04196173,0.010921625,-0.048710342,0.02015583,-0.046660606,-0.034685493,0.026857942,-0.016860915,0.016947407,-0.017511116,0.026436627,-0.0417341,-0.011716656,-0.024263209,-0.0035006746,-0.002872238,0.038822815,-0.053452145,0.045712695,0.0677122,0.01552791,0.07507546,-0.010861184,-0.002574271,-0.0033519075,0.021932203,-0.03225765,-0.03854276,0.01261903,0.04642289,0.00526802,0.02