insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8477833','utility','8477833','US','7/2/2013','A 1/n-rate decision feedback equalizer (DFE) and method include a plurality of branches. Each branch includes a summer circuit configured to add a feedback signal to a received input, and a latch configured to receive an output of the summer circuit in accordance with a clock signal. A feedback circuit includes a multiplexer configured to receive as input, an output of each branch, the multiplexer having a clocked select input and configured to multiplex the output of each branch to assemble a full rate bit sequence, and a filter configured to provide cancellation of intersymbol interference (ISI) from the received input to be provided to the summer circuit of each branch.','Circuits and methods for DFE with reduced area and power consumption','B2',11,'ipg130702.xml',0,'[-0.0012262821,-0.032299474,-0.034255702,-0.04803382,0.049814798,0.07374504,0.051442828,0.05153367,0.038943145,-0.085403875,-0.05904825,-0.016053822,0.017989613,-0.047934286,0.028573034,-0.04549777,0.057129975,-0.03838787,-0.072287716,0.0015109604,0.024528602,-0.07277421,-0.04831187,0.009552605,0.01895361,-0.09483472,0.029374618,-0.01749781,-0.028335234,0.07699532,0.0044449423,-0.055187676,0.06923223,-0.034296136,-0.033426166,-0.015752984,-0.0048999456,0.057965066,0.034094654,-0.03597071,0.01747515,0.01579103,-0.032904174,-0.011025715,-0.066963226,0.03646848,-0.041286565,0.014286752,0.047333855,0.007467175,-0.030518329,0.011175237,0.038514573,0.035514344,0.035058822,-0.020071926,0.055779666,0.026915794,0.007427948,-0.030869216,-0.018203342,-0.054774713,0.016726196,0.020340981,-0.0046476326,0.074428186,0.050003182,0.0014868,-0.009671259,-0.054635942,-0.0006415021,-0.020386353,0.033189174,-0.063957304,0.007385029,-0.021030094,0.013460941,-0.026857354,-0.0126638105,0.029205553,-0.048473597,-0.0385354,-0.057311203,0.012