insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8482538','utility','8482538','US','7/9/2013','An information input device includes an input panel and one or more circuits. The one or more circuits are configured to determine first, second and third representations of possible proximity of an object to an input panel from first, second and third input frames, respectively. The second input frame is generated after the first input frame, and the third input frame is generated after the second input frame. The one or more circuits are configured to determine whether proximity of the object to the input panel is detected for the second input frame, based on the third representation, if the first and second representations are not similar.','Information input device, information input method, information input-output device, storage medium, and electronic unit','B2',36,'ipg130709.xml',0,'[-0.038075164,-0.059635453,0.029981118,0.023185268,0.012329377,0.023781398,0.07717841,-0.019842109,0.03556165,-0.03155347,-0.026323857,0.027913813,0.083582506,-0.06806788,0.026597584,-0.007902946,0.01978704,-0.07360558,0.0058387974,-0.07871112,-0.006085297,-0.07336951,-0.06045835,0.015081917,0.07477105,-0.093686014,0.016980045,-0.02050224,-0.0737354,0.06323832,0.023302553,-0.031788614,0.026719905,-0.0030865634,-0.023329675,-0.0063981703,-0.0035601195,0.03005027,0.06414236,-0.029359324,0.0028827726,-0.032076206,0.00690592,-0.043985568,-0.030607285,0.024921296,-0.038993925,0.00824909,0.01370508,-0.07478033,-0.008073661,0.037005957,-0.018393582,0.04083212,0.03430751,0.015916683,0.017250678,0.01751341,-0.029255377,0.0109926285,-0.031065835,-0.03631752,0.047826782,0.01924964,-0.03476025,0.06780359,0.0041497964,-0.0069643725,0.016763179,-0.06252665,-0.0017347425,-0.03915185,0.00445462,-0.06916714,0.028303491,-0.023871832,0.02972264,-0.074576676,-0.009905624,0.047366284,-0.04922919,-0.08629588,-0.04637