insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8483643','utility','8483643','US','7/9/2013','Disclosed is a harmonic rejection mixer that makes it possible to suppress high-frequency response, while keeping the number of gm elements from increasing. In a harmonic rejection mixer that regulates the waveform of an output signal by mixing outputs of multiple mixers that are connected in parallel with the latter stage of multiple gm elements, some of the gm elements are shared by I phase and Q phase by using a control signal with a duty ratio of less than 50% to drive at least some of the mixers, and then using the period in which the I-phase mixers are inactive to activate the Q-phase mixers.','Harmonic rejection mixer','B2',10,'ipg130709.xml',0,'[-0.0042115343,-0.010378132,0.01622942,-0.035810053,0.010552278,0.048105046,0.025620589,0.018770479,0.045614887,-0.07213552,-0.028166886,-0.019857254,0.06371484,-0.111233614,-0.0039038574,-0.017326329,0.019205593,-0.07193734,0.012431671,-0.0010521015,0.073746346,-0.09915966,-0.07765383,0.0059265164,-0.01252879,-0.122006156,0.02683726,0.001703176,-0.004560534,0.086542234,-0.0059103807,-0.048037454,0.06308289,-0.047400307,-0.018466426,-0.049667325,-0.017938843,0.030388048,-0.0056593223,0.050327033,0.060921945,-0.056499794,0.014245315,0.013056454,-0.027592218,0.041488014,-0.049536634,-0.02604337,0.05223693,-0.020910826,0.008137017,0.022009635,0.012064164,0.023002088,-0.008585218,-0.030156532,0.0112575,0.035196204,-0.032490123,-0.00032311433,0.010958065,-0.0705794,0.04621269,0.033578638,-0.014582905,0.08611586,0.012295018,-0.012795902,0.05730168,-0.034392737,-0.040019587,-0.027054615,0.05721692,-0.06794086,-0.023168145,0.00967831,0.03379648,-0.025698742,-0.0033219112,0.048590362,-0.08287045,-0.04922483,-0.034793235,-0.027446566,0.08285892,-0.052284114,-0.024652937,-0.021897146,-0.0049488298,0.016968722,0.028990759,0.0062118997,0.00950882