insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('4422264','utility','4422264','US','12/27/1983','A safety gate assembly includes a pair of gates guarding a pre-selected area, the gates being coupled together with cables and pulleys so that one of the gates is always closed to prevent someone from accidentally walking through the area and being injured. The gates are balanced to make movement thereof easy and self-biased to stably open and closed positions.','Safety gate assembly','A',8,'pftaps19831227_wk52.zip',0,'[0.026678754,-0.049176693,0.0037906733,-0.034883436,0.08597925,0.029464103,0.017718295,-0.021117005,0.008316089,-0.03714759,0.012442222,-0.009123002,0.057405066,-0.023522055,0.08242612,0.006890552,0.02867105,-0.02479667,0.0034628275,-0.06861559,-0.01954946,-0.04403927,-0.05190937,0.02804527,0.055997547,-0.10869011,0.03156522,-0.044879664,-0.018637469,0.055788618,-0.07203353,-0.04749552,0.017175801,-0.03982853,0.0043127565,-0.019331543,0.01779346,-0.0009568912,0.013124623,0.013358605,0.044921756,-0.013898255,0.029989505,-0.031004442,-0.0016637117,0.02410708,-0.04413265,0.0029065146,0.034764018,-0.04215671,0.023259483,0.0637816,0.05805429,0.028189775,0.05641248,0.04657586,0.013700712,0.031688515,-0.031082686,0.036585525,-0.019959506,0.027933119,-0.050991196,0.025843455,-0.024334358,0.032984316,0.007376816,0.03785783,0.018964328,-0.04761033,0.012640093,-0.075746,0.03087467,-0.013389454,-0.013640887,-0.011095736,-0.033808567,-0.021840971,-0.032291703,0.04268459,-0.0727282,-0.026387453,-0.048456162,-0.049744148,-0.013961753,-0.059510045,0.034553833,-0.012576685,0.0010167465,0.027292237,0.018064268,-0.021229798,0.02733402,0.0035957606,0.0011255374,0.03508619,-0.01611985,0.0697833,-0.04550018,0.037271433,0.02149869,0.02720617,-0.011713336,0.0016099344,-0.032092158,0.028062653,0.00061234005,0.014230057,0.001781473,-0.06619149,0.04568825,-0.017624574,-0.055445116,0.01942307