insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8493584','utility','8493584','US','7/23/2013','An information processing apparatus configured to transmit print data to a printing apparatus to perform printing includes a determination unit configured to determine whether a selected complex print setting including a plurality of setting values requires resolution of a conflict of setting values, and an execution unit configured to execute print processing using the setting values without performing conflict resolution of the setting values, if the determination unit determines that the complex setting does not require the conflict resolution of the setting values, and execute print processing using the setting values that have undergone the conflict resolution of the setting values, if the determination unit determines that the complex setting requires the conflict resolution of the setting values.','Information processing apparatus for performing printing and determining whether a conflict resolution of the setting values in a complex print setting is required','B2',5,'ipg130723.xml',0,'[-0.0057583544,-0.02081998,0.04043531,0.0035980241,0.017284261,0.03524608,0.016446339,-0.010275113,0.035987765,-0.07206058,-0.008994975,0.060642213,0.04253885,-0.050875723,0.047821272,0.0008688827,0.0282924,-0.105317526,0.018974377,-0.044707015,0.07401037,-0.051061217,-0.0018790759,-0.0014329372,0.014402156,-0.10088751,-0.045159996,-0.009350687,-0.057446625,0.05049594,0.035265982,-0.025502088,0.06280892,-0.016094705,0.0116901705,0.013719506,0.028493993,-0.010756308,0.06465747,-0.040555578,0.07950622,-0.008025468,-0.020065278,-0.036795978,-0.039556593,0.038444187,-0.019975781,0.037567403,0.0154070435,-0.05092039,-0.010147075,0.06593443,0.025570277,0.05062563,0.051860727,0.014412095,0.03580827,0.0046772663,-0.013747682,0.002053144,0.0018982921,-0.046604637,0.047898114,0.020705676,-0.0021409078,