insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6531081','utility','6531081','US','3/11/2003','A slider device and methods of making. The slider device is for use with a resealable package having a zipper closure, and includes a top wall with first and second ends, a spreader depending from the top wall, a first sidewall with a first hook construction extending therefrom, and a second side wall with a second hook construction extending therefrom. An extended length of profiled material is extruded and can be converted to form individual slider devices. The spreader can be tapered, either in its width or the distance in which is depends from the top wall. These slider devices can be incorporated into resealable packages.','Profiled extruded slider devices and methods','B1',13,'pg030311.zip',0,'[0.014316873,-0.04962523,0.039082967,-0.020064894,0.046232868,0.030436935,0.008441291,0.013791097,0.0547676,-0.02629071,-0.017769026,0.004968406,0.048174426,-0.054556962,0.043996,0.0054319813,0.042139407,-0.06522027,-0.0064215004,-0.041328598,0.01493042,-0.06776468,0.0299506,0.032071475,0.07183386,-0.10763098,-0.029515248,-0.0014431743,-0.05187621,0.073935896,-0.018540021,-0.0944515,0.035805758,0.00950741,-0.028944885,-0.048405416,0.007709151,0.029402977,0.021427054,0.0041978373,0.033591785,-0.046790008,0.024967328,-0.05927244,-0.0007483796,0.030925658,-0.032018993,0.025158528,0.066247046,-0.033600863,0.026268331,0.117131986,0.016240587,-0.067524135,-0.014690973,0.017633125,0.040423423,0.06991506,-0.009058781,-0.0050153234,0.012851009,-0.019091824,-0.04313766,0.033316586,-0.06405016,0.046369795,0.014751534,0.007870704,0.0166184,-0.01209718,-0.0035178077,-0.026321165,-0.01663407,-0.032480545,0.006646137,-0.05329018,0.040663432,-0.023157857,-0.052717067,0.072345816,-0.05197422,-0.017240832,-0.03860336,-0.007930474,-0.0053009856,-0.03234554,-0.037078805,-0.02171269,0.06805072,0.02103409,0