insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6533059','utility','6533059','US','3/18/2003','A dual exhaust system transmission cross member that replaces an existing single exhaust system transmission crossmember. The crossmember includes a center portion that mounts the transmission, a pair of intermediate portions that extend from the center portion and straddle the tail piece of the transmission, and a pair of outer portions that extend from the pair of intermediate portions, respectively, and are attached to the pair of side rails. Each intermediate portion is inverted U-shaped so as to accommodate the head pipes of the dual exhaust system. The outer portion that is positioned on the passenger side of the vehicle slants rearwardly from the associated intermediate portion, while the outer portion that is positioned on the driver side of the vehicle slants forwardly from the associated intermediate portion.','Transmission cross member for accommodating a dual exhaust system and replacing an existing transmission cross member accommodating a single exhaust system','B2',13,'pg030318.zip',0,'[-0.013222626,0.018680742,0.05639901,-0.009042159,0.05054611,0.05035598,0.026359756,-0.020001171,0.02649142,-0.054682676,-0.048220076,0.0362429,0.08634052,-0.015852178,0.045827907,0.003388292,0.027232125,-0.058558203,0.003974258,-0.024248552,0.015434913,-0.10921473,-0.03785439,0.051762614,0.058539476,-0.092558585,0.02064506,-0.032343857,-0.029947558,0.04330492,0.03299083,-0.101399444,0.05644768,-0.007263271,0.0103572495,-0.0421612,-0.050783973,0.026165951,0.0013920198,0.04710605,0.029132742,-0.018864783,0.00890575,-0.005631257,-0.05534251,0.057420816,-0.0034989028,0.0003637895,-0.0110372715,-0.028275913,0.024652395,0.07829283,-0.005001048,-0.06286376,0.0039889365,0.030742459,-0.0056962427,0.050395384,-0.04883855,-0.03796976,-0.007886579,-0.04157339,-0.048748918,-0.006023495,-0.0602495