insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6544943','utility','6544943','US','4/8/2003','A multi-phase detergent tablet comprising: a) a first phase in the form of a shaped body having at least one mould therein; and b) a second phase in the form of a compressed, body adhesively contained within the mould, wherein the tablet composition comprises one or more detergent actives which is predominantly concentrated in the second phase, and wherein the second phase additionally comprises a disrupting agent. The multi-phases tablets provide improved dissolution and cleaning characteristics together with excellent tablet integrity and strength.','Detergent tablet','B1',12,'pg030408.zip',0,'[0.010978473,-0.028517785,-0.021218456,-0.011681867,-0.027496047,0.067324124,0.0094116,0.028712304,0.040559094,-0.00065657496,-0.086954735,-0.00953442,0.055378847,-0.08800453,0.010940819,-0.029550146,0.029073393,-0.022989796,0.03463059,-0.010280758,0.022167858,-0.06776888,-0.050635595,0.021625066,0.042705495,-0.026422312,-0.06658542,0.0028799959,-0.059642874,0.026821032,0.011073642,-0.0007559585,0.061406005,-0.031610426,-0.012539393,0.022373276,0.0569024,0.013481624,0.013132448,-0.0028152408,0.083598986,-0.008362983,-0.015167445,-0.072010025,-0.025765058,-0.020012343,0.011469788,0.027601961,0.02893082,-0.022112306,0.047401432,0.04315688,-0.009296484,-0.04673135,0.10109777,0.013510043,0.025720747,0.03512836,-0.021543832,0.021969989,0.016438572,-0.034629848,-0.023791831,0.033919435,-0.04740485,0.03824469,0.06571384,0.011019991,0.0035237144,-0.089085236,0.01627865,-0.015766669,-0.030333288,-0.049739562,0.008709762,-0.037772305,0.03484015,0.02956512,-0.003981858,0.060231026,-0.02623539,-0.063258074,-0.007899598,0.03563244,-0.04391832,-0.0378013,-0.00031715562,-0.033081006,-0.03732923,0.04677637,-0.051346917,0.022188256,0.051842503,0.007851926,-0.01913795,0.044717487,0.06618203,0.06324522,0.0095