insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6549344','utility','6549344','US','4/15/2003','A retro focus type wide-angle lens comprises a front group having a negative refracting power and a rear group having a positive refracting power. The front group comprises a first lens made of a negative meniscus lens, a second lens made of a biconvex lens, a third lens made of a negative meniscus lens, and a fourth lens made of a positive meniscus lens. The rear group comprises a cemented lens in which a fifth lens made of a negative lens and a sixth lens made of a positive lens are cemented together, and a seventh lens made of a positive lens. This wide-angle lens further satisfies predetermined conditional expressions.','Retro focus type wide-angle lens apparatus using the same','B2',5,'pg030415.zip',0,'[0.04615155,-0.015369233,-0.012122512,0.0039789164,0.027416551,0.039646342,0.0051748576,-0.03359392,0.053289965,-0.0689608,-0.03013254,0.007015268,0.03169242,-0.05514371,-0.002089566,0.003554054,0.048159152,-0.053976964,-0.058153875,-0.001318394,0.04948909,-0.02184458,-0.06810358,0.00987904,-0.022383392,-0.090325706,0.03646455,0.009223024,-0.0258893,0.07711622,0.04856258,-0.022620609,0.07166937,-0.023007,-0.02065945,-0.039349653,-0.012651644,0.028020853,-0.0047884975,-0.017023155,0.0561057,-0.080138266,0.022861127,-0.038395364,-0.123498514,0.055399396,-0.020635614,0.025791354,-0.016621852,-0.06370856,0.026309028,0.034428705,-0.0027828212,-0.029410185,0.020977648,0.04755725,-0.0027127895,0.022248607,-0.0761071,-0.035514787,-0.047281038,0.02698336,-0.018721616,0.030904839,-0.02726424,0.062427707,-0.0014101396,0.033598673,0.022744184,-0.025077123,0.027672507,-0.0025235426,0.017323934,-0.030824475,-0.007404118,-0.026096083,0.010272547,0.012927368,-0.036799338,0.030536518,-0.09694244,-0.027622009,-0.0360382,-0.039197955,0.030776717,-0.031285144,-0.11519272,0.0016416712,-0.019510003,