insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6549428','utility','6549428','US','4/15/2003','A device for supporting and fixing bus-bars in cabinets for switchboards, comprising:a first element, constituted by a body made of insulating material, which has a first side provided with means for direct engagement to a supporting frame and a second side provided with a plurality of first seats for coupling to corresponding bus-bars;a second element, constituted by a body made of insulating material which has a shaped side along which a plurality of second seats are provided for coupling to the bus-bars, the first and second elements being mutually connected in order to geometrically couple the first and second seats and to clamp the bus-bars inside the seats.','Device for supporting and fixing bus-bars','B1',51,'pg030415.zip',0,'[-0.022034392,-0.014308425,-0.0102275545,-0.0030163855,0.05183802,0.04309659,0.03700783,-0.004368779,0.01874042,-0.006679074,-0.07245757,0.022088956,0.079627834,-0.036269985,0.027409635,0.000787762,0.015694706,-0.06459518,-0.002048349,-0.031161893,0.012904681,-0.09679145,-0.036257066,-0.016004695,0.0470921,-0.103457615,0.026393848,0.0003096936,-0.02901967,0.05896107,-0.014856855,-0.019352155,0.05316127,-0.0053299316,0.01804096,0.026652385,-0.006136948,-0.01102271,0.044785812,0.031217292,0.06118407,0.031263314,0.011372366,-0.006408436,-0.02201351,0.05788869,-0.017294647,0.048270274,0.012985326,-0.030936936,0.028875194,0.043464046,0.0069065453,-0.06366372,0.034913644,0.01628165,0.020951578,0.041254543,-0.043626606,0.019286737,0.006503942,-0.05674699,-0.025915936,-0.0333888,-0.06266148,0.044063196,0.008649618,0.032520194,0.027296897,-0.051145196,0.05224355,-0.06433084,0.017927062,-0.07400857,0.00025011785,-0.0197983,-0.005973236,-0.00937086,-0.03868747,0.07114141,-0.047670208,-0.0059704753,-0.018443087,-0.041347373,-0.031527147,-0.03415657,-0.02263196,-0.