insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6556789','utility','6556789','US','4/29/2003','A diaphragm switching apparatus according to the present invention comprises a gear adapted to rotate in response to a driving force of a focus motor used for driving a focus lens; a shaft for rotatably supporting the gear; a diaphragm switching means, secured to the shaft 12 and adapted to rotate together with the shaft, for switching a diaphragm upon rotating; an intermediate member engaging the diaphragm switching means so as to rotate together with the shaft and being slidable axially with respect to the shaft; an urging means for urging the gear away from the diaphragm switching means by way of the intermediate member by receiving a reaction force from the diaphragm switching means; and a holding part 12a for receiving the gear urged by the urging means.','Diaphragm switching apparatus','B2',5,'pg030429.zip',0,'[-0.018539606,-0.004930133,0.025880234,0.010958752,0.03514867,0.07001539,0.016679522,-0.070673995,0.055016622,-0.04108647,-0.08911914,0.006747716,0.028669314,-0.059568495,0.030624298,-0.019714594,0.08590781,-0.06324332,-0.034783676,-0.045922775,-0.034671564,-0.041569773,-0.070650436,-0.0029201491,0.023767076,-0.11448297,-0.004863124,-0.021130504,-0.043240987,0.054866128,0.010341225,-0.056399375,0.06568901,0.0042771893,-0.0077613806,-0.029727647,-0.00481678,-0.025487753,0.011884557,0.0003276938,0.047652416,-0.030256616,0.019079618,-0.015037979,-0.044920806,0.035618145,-0.0034177627,0.037903316,0.04362819,-0.021514991,0.021703517,0.09051987,-0.011631646,-0.044537812,0.021279372,0.04187253,0.04191076,0.053037953,-0.003943607,0.004201767,-0.0009301075,-0.046420332,0.005751723,0.026990755,-0.0006184985,0.072471745,0.013723087,0.011048456,0.0013208672,0.002507896,0.0047833514,-0.016196351,0.07084358,-0.047477197,0.003596438,0.0011162498,-0.0003110377,-0.011732987,-0.07492170