insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6556794','utility','6556794','US','4/29/2003','The carrying apparatus comprises a carrying device for carrying an object to be carried, along a carrying route, a heating device for heating the object being carried along the carrying route, a control device for temporarily stopping and keeping the object being carried along the carrying route, and a detection device for detecting whether the object is positioned at the heating device, when carrying of the object is temporarily stopped by the control device, wherein if the detection device detects the object positioned at the heating device, the control device controls operation of the carrying device so as to carry the object until the detection device does not detect the object any more, and then to stop carrying of the object.','Carrying apparatus and image forming apparatus','B2',12,'pg030429.zip',0,'[-0.017701373,-0.005709201,0.07909856,-0.0015812262,0.010988547,0.030653125,0.012426073,-0.005399828,0.07796256,0.008961947,0.015428777,-0.015933998,0.052060686,-0.06277871,0.07494671,0.01968926,0.0626757,-0.0535086,0.017174166,-0.07535459,-0.011908083,-0.06358046,-0.0009599239,-0.0025759577,0.017379716,-0.084808975,-0.012824837,-0.017025629,-0.07662278,0.027491422,-0.03968934,-0.054852214,0.040611878,0.0033208632,0.039693367,-0.04145714,0.05217,-0.0016665205,-0.008366343,0.0074680857,0.054395784,-0.033526126,0.024673473,-0.0266473,0.021889009,0.010522158,-0.016178088,0.021876344,0.050695583,-0.06502456,0.018864796,0.08327849,0.04598938,-0.0038730234,-0.0256747,0.035998877,-0.03364426,0.054826356,-0.011980311,0.043658346,0.010989681,-0.06794746,0.021868609,0.0075777303,-0.04599714,0.05749622,0.028762901,0.022528538,0.0022542027,-0.0633261,0.020017747,-0.018554393,0.02716655,-0.021877028,-0.010086454,-0.0135979615,-0.023508174,-0.011058124,-0.041407675,0.047465086,-0.03874714,-0.