insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('4418272','utility','4418272','US','11/29/1983','An electric heater, especially for small electric appliances, such as hair roller heaters, egg boilers, or the like, and a method of making same utilizes at least one heating element having contact-making zones on opposite planar parallel surfaces thereof, electrical connection elements in the form of essentially planar contact plates, a contact plate being placed on each of the opposite surfaces, and a holding member having a heat conducting, electrical insulating layer upon a surface thereof. The holding member is bent into a U-shape so as to hold the contact plates clamped fast to the heating elements between legs of the U-shape of the holding member and with the insulating layer disposed on an inner surface of the U-shape between the plates and holding member. In accordance with a preferred embodiment, the insulating layer is of a resilient material having a heat-conductive additive distributed therethrough and the heating elements are formed of PTC material.','Electric heater','A',13,'pftaps19831129_wk48.zip',0,'[-0.040442493,0.0039903247,0.025608687,-0.02637457,-0.0011382963,0.04029036,0.008982489,0.0043475907,0.08212103,-0.05131924,0.0032965676,-0.016170707,0.05801153,-0.1309369,0.01995729,0.0048974864,0.045138318,-0.100048915,0.005552669,-0.017497001,0.016919931,-0.09760005,0.03446974,-0.0070579415,0.024523122,-0.09596132,-0.004099265,-0.01818559,-0.051328532,0.070314884,-0.022469405,-0.013452734,0.051048983,-0.027115881,0.012544298,-0.02612439,0.012197824,0.016441362,0.013513882,0.010621457,0.05391379,-0.000655508,0.019785495,-0.086775415,-0.011462785,0.029868172,-0.052288245,0.012014444,0.03608718,0.0034052324,0.037410088,0.06920363,0.0060275737,-0.043623727,-0.011936771,0.051202606,-0.028513193,0.076944284,-0.05171919,0.02340916,-0.009310606,-0.10366267,-0.035216246,-0