insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('4419037','utility','4419037','US','12/6/1983','An auger-hopper construction for mounting at the tailgate of a truck includes a pair of hoppers, one of which is stationarily and removably mounted to the truck, and the second of which is pivotally mounted to the first hopper adjacent an opening in the bottom of the first hopper. The second hopper also includes an opening adjacent its bottom at which an auger tube is swivelly mounted. The auger tube, by virtue of the pivotal and swivel mountings is pivotable in a 90.degree. arc in a plane perpendicular to the axis of the pivotal movement and is swivelable in a 180.degree. arc in a plane which is parallel to the axis of the pivotal movement.','Truck auger-hopper construction','A',20,'pftaps19831206_wk49.zip',0,'[-0.046757262,0.005518116,-0.013479524,-0.030294081,0.053313576,0.028553708,0.031956676,-0.02159687,0.023956338,-0.0017446452,-0.06569971,-0.017704159,0.100062646,-0.02606086,0.028660819,0.012704957,0.0068294676,-0.02076518,-0.031915966,-0.049490146,-0.015666436,-0.0654417,-0.02025546,-0.018380154,0.046698388,-0.059546895,-0.02012856,-0.009750035,-0.06592167,0.021553,-0.011430436,-0.046632525,0.06532812,0.029088145,0.055140402,-0.055642128,0.0028953943,0.053360898,-0.045571737,0.031280678,0.08513508,-0.028556138,0.016876781,-0.05849711,-0.017479092,0.03329024,-0.03457797,-0.02168025,0.009894062,-0.07385637,0.046328083,0.058102548,0.024169087,-0.014348177,0.004786906,0.022926785,0.05033977,0.028768357,0.004446467,0.030399494,0.0014185094,-0.07061171,-0.038920768,0.05103546,-0.028957898,0.03467092,0.0107765095,0.009130606,0.027746791,-0.03867905,0.013354971,-0.061012622,0.01717555,-0.07354656,0.0055034677,-0.043418013,0.042621106,-0.037069254,-0.022234999,0.046713132,-0.05189789,-0.06838029,-0.059060253,-0.017658856,-0.0023419454,-0.045259494,-0.02430054,-0.00055982627,0.0330