insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('4419902','utility','4419902','US','12/13/1983','A constant strain load cell for measuring forces applied to the cell which includes a parallelogram shaped body having fixed and movable end constraints interconnected by upper and lower flexures with flexing areas at the opposite ends of the flexures functioning as sensing beams and on which strain gages are mounted. The flexing areas are formed so that bending stresses caused by applied loads are maintained constant over the flexing areas or regions. The load cell can be easily machined or extruded and the capacity can easily be varied dependent only on the overall size.','Constant strain load cell','A',7,'pftaps19831213_wk50.zip',0,'[-0.013775105,-0.012540878,-0.019333228,-0.0077240528,0.032986965,0.051815484,0.028299283,-0.027398339,0.039236233,-0.009871759,-0.046780825,-0.024005948,0.05783157,-0.076261066,0.015184984,-0.02716433,0.013942434,-0.05216445,-0.058159515,-0.013597102,0.018369837,-0.08893475,-0.05546498,0.045866445,0.03324778,-0.07735885,0.016321106,-0.051918834,-0.06490827,0.070479155,-0.039085742,-0.03245196,0.045182455,-0.017943185,0.05528708,-0.011671068,0.03325956,0.017787911,0.04493717,0.0021834879,0.07584612,-0.058720365,-0.011805613,-0.010294281,0.00031558334,0.046204366,-0.027641196,-0.0039322283,0.08312828,-0.040565833,-0.013882978,0.008512604,0.016686674,-0.009449722,0.008573613,0.058822516,0.077007726,0.040386852,0.0045193997,0.023615293,-0.012547148,0.007164498,-0.0035189607,0.024446623,-0.020824784,0.046987314,-0.019202368,0.06698319,-0.0036144282,-0.042907204,-0.035834637,-0.04248523,0.051951304,0.0074539864,-0.047363874,-0.031693738,0.023300463,-0.029633969,-0.061469287,0.04327488,-0.007968678,-0.052886777,-0.05151018,-0.012097326,0.026599314,-0.0329136,-0.032510456,0.027128791,-0.0023736358,0.043761827,0.024445985,-0.0091626495,0.03349251,0.0211420