insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('4421589','utility','4421589','US','12/20/1983','A laminator for laminating and/or encapsulating a multilayer laminate assembly is disclosed. The laminator includes a processing chamber designed to receive the laminate assembly. The processing chamber is provided with independently controllable temperature, vacuum and pneumatic pressure capabilities for effecting optimum processing conditions for particular materials and configurations. The laminator features a double-vacuum system and a choice between two automatic cycles: a lamination cycle and a lamination-and-cure cycle. Preferably, the laminator is microprocessor controlled and is provided with a control panel where the processing parameters are set and monitored.','Laminator for encapsulating multilayer laminate assembly','A',10,'pftaps19831220_wk51.zip',0,'[0.027385898,-0.008855022,0.05316001,-0.0151355015,0.023896351,0.018907674,-0.030887472,0.025231825,-0.00638493,-0.0044410694,-0.019396028,-0.028848365,0.01139977,-0.09503649,0.045375705,-0.025510352,0.017071247,-0.057948362,-0.0041511604,0.019495824,0.01791906,-0.10571899,-0.02558934,-0.0003711024,0.065247245,-0.087314755,-0.021275273,-0.024457065,-0.029878745,0.021743745,0.0050094603,-0.056996696,0.062031616,-0.011393425,0.02350046,0.007822977,0.02111011,0.0014934716,0.024034085,0.0005849664,0.039310955,-0.046314336,0.059797537,-0.052547596,-0.0364447,0.07503183,-0.05032791,-0.015679419,0.04800471,-0.030863058,-0.010988636,0.06908815,0.013148774,-0.031546183,0.04588365,0.03742993,0.01778692,0.022433361,-0.0019409762,0.046152037,0.012995861,-0.05267672,0.009758695,0.017357685,-0.0063371416,0.058663357,0.0077543682,-0.0021881103,-0.0042260317,-0.046871793,-0.036062215,-0.02010929,0.00986519,-0.08263292,0.0047681816,-0.020580506,0.025449742,-0.0077279247,-0.06651815,0.077869244,-0.022551337,-0.07800124,-0.034852054,0.01