insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('4427692','utility','4427692','US','1/24/1984','Spherical agglomerates of dihalodimethylhydantoins and dimethylhydantoins are prepared by feeding a mixture of the hydantoins together to the surface of an agglomerating disc in conjunction with a spray of water, and subsequently drying the agglomerates. These agglomerates possess a hard structural integrity and exhibit a uniform and controlled dissolution when placed in an aqueous environment, thereby rendering them suitable for a variety of applications including automatic dishwashing detergents, industrial bleaches, as well as disinfectants for cooling towers, swimming pools and spa waters.','Agglomerated halo-hydantoins','A',13,'pftaps19840124_wk04.zip',0,'[-0.059748944,-0.025838718,0.012226883,-0.026766693,0.014888866,0.04264428,0.007263125,0.026415048,0.0682858,0.0039775507,-0.027281838,-0.020298084,0.003699978,-0.070460774,0.0019019205,0.011945816,0.0489713,-0.06935046,0.060992807,0.010467455,-0.0043328535,-0.035123248,-0.038613297,-0.024136987,-0.009517068,-0.06468742,-0.021580005,-0.02512086,-0.037977125,0.05421989,0.049752545,0.05901019,0.061157245,0.0015288227,0.018394042,-0.029460223,0.020233227,-0.010544494,-0.02112372,0.027627757,0.045065332,-0.031384632,0.01995625,-0.0006160408,0.0016340413,-0.026755773,0.02006754,0.024340114,0.0026199946,0.011240896,-0.019705595,0.017103048,-0.029326098,-0.019305388,0.092749834,-0.014593497,0.0038426344,0.030703733,0.018715354,0.019348444,0.00948672,-0.04169088,-0.031588335,0.010494414,-0.037722662,0.023705266,0.047663108,-0.010172483,0.031796884,-0.0083791725,-0.05884773,-0.0047367457,0.002245157,-0.049716044,0.02843814,-0.05150151,0.037003487,0.023501616,0.04785738,0.055661492,-0.049929477,0.026749128,-0.010155943,0.013315917,0.004981891,-0.026706427,-0.047881335,0.0076786187,-0.05921719,0.06635374,-0.011567541,-0.02980596,0.0493