insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('4434074','utility','4434074','US','2/28/1984','Solutions or slurries of waste material in water are dewatered and encapsulated within a polymer for disposal, comprising the operations of removing water therefrom with azeotropic mixture evaporation and encasing the dewatered waste residue in an organic polymer. The method and system disclosed are especially useful for the safe disposal of radioactive waste.','Volume reduction and encapsulation process for water containing low level radioactive waste','A',33,'pftaps19840228_wk09.zip',0,'[-0.048399895,-0.014232407,0.015214335,-0.10129186,0.028622383,0.072364524,-0.00785228,0.08088067,0.03482308,-0.011255176,-0.010027683,-0.04179364,0.03759747,-0.05704872,0.09275387,-0.011549052,0.048937265,-0.0713673,0.07279255,0.025231384,-0.013967671,-0.06973115,-0.00942784,0.03598367,0.015526628,-0.08196978,-0.051271923,0.01970145,-0.07584196,0.018847104,-0.020575125,-0.019218417,0.03771686,-0.04414839,0.037151664,-0.050665345,0.071130745,0.017331548,0.047822587,0.03124304,0.020613799,-0.028447293,0.045785256,0.0016136775,0.01147138,0.013030783,0.0065494436,0.005197483,0.065154076,-0.07670639,0.04440259,0.021387404,-0.026843552,-0.016500717,0.04453128,0.04122605,0.008453455,0.03019946,0.02486582,0.026831528,-0.015078411,-0.059542492,-0.0143429,0.026018951,-0.035409946,0.06971669,0.03980734,-0.011213282,0.016517669,-0.08513038,-0.013263164,-0.0067806207,0.022283446,-0.079097025,0.018196408,-0.016975192,0.0072759897,0.036646012,-0.018062469,0.071175925,-0.010417159,-0.038746342,-0.020437267,0.03242408,0.010526536,-0.025861954,-0.020989489,-0.01387956,0.071954004,0.032491386,0.032569066,-0.028398095,0.07707241,0.03243234,0.028224494,0.091969095,-0.025330989,0.05459592,0.0076820096,0.024254052,0.04440951,0.0040489435,-0.0007254101,-0.03243915,0.002916614,0.05011498,-0.031749226,-0.025299065,-0.002