insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('4440604','utility','4440604','US','4/3/1984','In the matrixing process used in the manufacture of lapping discs employed in the production of videodisc styli, it has been found that the separation of the electroformed parts from the parts on which they are formed can be performed effectively and simply by heating the assembly of the electroformed part and the part on which it is formed to an elevated temperature which causes the parts to separate from each other without distortion of the lapping grooves and without damage to either of the parts.','Method for the manufacture of lapping disc for forming keels on videodisc styli','A',9,'pftaps19840403_wk14.zip',0,'[-0.037050378,-0.0016903838,0.069474325,-0.03724922,0.0054299133,0.074531406,-0.00949822,0.03867818,0.03311531,-0.020757504,0.015805785,0.0074023088,0.041709118,-0.032290418,0.037368827,-0.0048636105,0.067875676,-0.055666663,0.021703614,-0.023131242,0.037657347,-0.10018329,-0.0016248431,-0.0010142581,0.033441853,-0.048889186,0.004515853,-0.0018406126,-0.038952164,0.051093865,-0.0014331829,-0.052909713,0.06940311,-0.024020502,0.051005002,-0.060001884,-0.007416755,-0.0050415066,0.050255224,-0.003168441,0.08249024,-0.024582928,0.034320828,-0.0033262176,-0.009206369,0.045478508,-0.043557297,0.0077248495,0.050826497,-0.06622812,-0.009060232,0.018414086,0.015977507,-0.029520543,0.05997347,0.07414766,0.042592168,0.043424252,-0.016404659,-0.03093899,0.0007714463,-0.036102165,0.0056705168,0.012882338,-0.08482062,0.036564507,0.05763858,-0.04933275,0.0021888944,-0.03437385,-0.045806162,-0.024108972,0.04665483,-0.084336415,0.00061457686,-0.04724125,0.0069460813,0.045323458,0.0023664585,0.08127792,-0.038573835,-0.014793852,-0.04380794,0.0023170765,0.024870168,-0.03233632,-0.017474256,-0.04374756,0.002640528,0.018790198,-0.02513153,0.02469171,-0.015736766,-0.0062914747,-0.0011376649,