insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('4446065','utility','4446065','US','5/1/1984','Novel oxime derivatives of phencyclidine are provided as precursors for conjugating proteins, either antigenic for the preparation of antibodies or enzymatic for the preparation of enzyme conjugates, which antibodies and enzyme conjugates find use as reagents in immunoassays. The combination of antibodies and enzyme conjugates provide for sensitive, accurate, rapid assays for phencyclidine without interference from commonly administered drugs, such as dextromethorphan, demerol and chlorpromazine.','Phencyclidine compounds and assays for its determination','A',9,'pftaps19840501_wk18.zip',0,'[-0.0025196995,0.011114136,0.009066993,-0.011591559,0.030847702,0.007511387,-0.022842927,-0.03485103,0.0071835103,-0.0474689,-0.05376168,0.00989676,-0.0145633705,-0.066559665,0.0313276,-0.014019416,0.017271012,-0.018382078,0.05516484,0.050423123,0.02023418,-0.06795037,0.029723713,0.03306553,-0.0063355165,-0.026647758,-0.01389072,0.030790364,-0.054413978,0.014582624,0.029540164,-0.042517576,0.04714932,0.032406796,0.010966739,-0.07046675,0.03612512,-0.04806465,0.022830429,0.033492047,-0.0037704033,-0.06786692,0.0032954614,-0.032752775,-0.0035342337,0.021085728,-0.0002599445,-0.004514664,-0.02092176,0.0069579068,0.01587695,0.012621763,0.005538661,-0.06657245,0.05027442,0.009138653,-0.024348533,0.06320003,0.036994126,0.073503114,0.0017131227,-0.0071542836,-0.038502634,0.024998944,-0.048915476,0.02486552,0.009853321,0.023398418,-0.015816052,-0.07590226,-0.06359426,0.014187202,-0.02952845,-0.03802858,-0.048827242,0.0055193384,-0.033441316,0.08450779,-0.0014092476,0.04328506,-0.10083893,-0.051105917,-0.07522343,-0.023901388,0.028463803,-0.036657616,-0.02527077,-0.019981645,-0.01889096,0.04509844,-0.06179567,0.0066280714,0.037718814,0.02691808,0.021893,0.012147299,0.005613742,0.103908986,-0.019302191,-0.