insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8135288','utility','8135288','US','3/13/2012','A photonic system and method are provided. The system includes an optical source configured to generate a carrier signal; and a modulator configured to modulate the carrier signal with a radio frequency, (�������RF�������) input signal to generate a modulated signal. The system also includes an optical filter configured to filter the modulated signal to generate a vestigial sideband modulated signal; and an optical detector configured to demodulate the vestigial sideband signal to generate an RF output signal. The system further includes a wavelength controller module configured to set an operating parameter of the optical source.','System and method for a photonic system','B2',24,'ipg120313.xml',0,'[0.028702853,-0.010910413,0.05321589,-0.036851376,-0.009280289,0.042573463,-0.0059381835,0.02543516,0.030713823,0.007554794,0.0218388,-0.021626487,0.032144256,-0.074190594,-0.0059841205,-0.0079874415,0.0058342805,-0.06563363,-0.06863563,0.0025830765,0.028398005,-0.0942519,-0.045449663,0.059755716,0.035960674,-0.08315011,0.04440421,-0.026336897,-0.054017268,0.03826761,0.015832154,-0.07600803,0.04271634,-0.023668941,0.028424233,-0.02990745,0.007506333,0.00770665,-0.0021836895,-0.022866515,0.04290302,-0.06250502,0.0067600096,-0.014736338,-0.050200257,0.088781305,-0.043632947,0.025126638,0.030690726,-0.009718469,0.03406633,0.04017411,-0.014622753,-0.022192204,-0.031573027,-0.0019261715,0.068838336,0.047983292,0.023063451,0.04288056,-0.009355707,-0.028840035,0.06870957,0.015477513,-0.013924691,0.06518139,0.0006650471,0.015287179,-0.022445256,0.009544602,0.00068461656,-0.04344859,0.081468016,-0.029687466,-0.006037601,-0.053399622,0.046771504,-0.011151967,-0.09625232,0.04067503,-0.059524845,-0.066392794,-0.029113065,0.019003637,0.022804106,-0.035297193,-0.01887115,-0.019670371,0.035685394,0.0