insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8139906','utility','8139906','US','3/20/2012','Provided is an optical wiring module. The optical wiring module includes a light source mounted on a surface of a substrate, a metal optical waveguide coupled to a transverse magnetic mode of light emitted from the light source and using a long-range surface palsmon polariton, and a photodetector. The optical wiring module has a simple structure enabling it to be further miniaturized and its yield to be increased.','Optical wiring module','B2',11,'ipg120320.xml',0,'[0.01810219,0.019858204,0.060459107,-0.02441523,0.0009915124,0.08619531,-0.04096377,0.0024176773,0.071349114,0.04064771,0.03143354,0.0055866996,0.010691583,-0.060498793,0.00074480945,-0.01688032,0.025033064,-0.08224015,-0.042798273,-0.00083754334,0.012290986,-0.043130964,-0.053087145,0.01713624,0.047121063,-0.051006634,0.009168479,-0.029195165,-0.03118471,0.05639934,-0.011216162,0.00023391822,-0.0009546369,-0.03976815,0.04312664,-0.03690762,0.028091554,-0.0053271665,0.0148818,-0.00830294,0.04099586,-0.03777364,0.042265493,-0.026708098,-0.016773893,0.07431781,-0.059793193,0.03953207,0.026623098,0.03725502,0.034079682,0.05928642,0.0046203528,-0.055046488,0.012231731,0.0072901812,0.03144518,0.07277339,0.030472176,0.040117897,0.032794118,0.0050391993,0.020414373,0.012319282,-0.06443554,0.07855864,0.007779821,0.040612977,-0.029543394,0.0019746246,-0.03082058,-0.05098733,0.043308318,0.0044855676,0.048154667,-0.04212564,0.015556328,-0.008881644,-0.061242513,0.035249643,-0.036967292,-0.017260399,-0.030899636,-0.009444476,0.015122618,-0.015020693,-0.01624707,-0.0116896145,0.015813999,0.049270988,0.06231661,-0.030300854,0.03304221,-0.011268428,0.04234126,0.024275655,-0.016001483,0.14623311,-0.01271739,-0.055189997,0.006963861,0.058926657,-0.014993597,-0.0722932,0.028714804,0.07870316,-0.008037585,-0.043313343,0.039666034,-0.06864