insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8142968','utility','8142968','US','3/27/2012','The disclosed embodiments are directed to an electrophotographic photoreceptor having a release layer. More particularly, the disclosure relates to an electrophotographic photoreceptor having a release layer which comprises an organosilane compound coated over the substrate surface. Other embodiments include methods for coating layer removal using a specifically configured electrophotographic photoreceptor having a release layer and methods for recovering a charge transport molecule.','Photoreceptor with release layer','B2',23,'ipg120327.xml',0,'[-0.017198544,-0.041626483,0.04907229,-0.020958351,-0.0007225745,0.06388714,-0.062562905,0.07748979,0.03663251,0.016292538,0.03093268,-0.049273822,0.006258944,-0.034100574,0.05031313,-0.025714403,0.042939384,-0.04527541,0.039901692,0.03764163,0.028759181,-0.050359145,-0.032760452,0.027944868,0.060625166,-0.07715769,-0.00564472,0.024714414,-0.062458377,0.09444994,0.0009795523,-0.016500598,0.066682644,-0.028609911,-0.042236052,-0.06315608,0.046511393,0.03317794,0.042111468,0.034777835,0.046492673,-0.0053421305,0.007384973,-0.042004596,0.006871914,0.03362121,-0.041139442,0.032975595,0.030040257,-0.050959833,0.018216206,0.08410537,0.045490935,-0.0049220873,-0.007654997,-0.012513136,0.034680493,0.062178005,0.01954124,0.05872423,-0.0046704398,-0.055512182,0.007680469,0.037882306,-0.050704565,0.06445247,0.024044292,0.014804041,-0.0017724559,-0.03772195,-0.03247908,-0.022677656,-0.00080173055,-0.10345482,-0.028295435,-0.022459753,0.06271329,-0.020902779,-0.03839518,0.090687715,-0.076989844,-0.0036502457,-0.052459355,0.014893735,-0.010732089,-0.0086490465,0.030877957,-0.015692964,-0.0009898178,0.075481065,-0.016707076,-0.0659544,0.016888915,-0.033593077,0.024720341,0.04013473,0.019079905,0.12622137,-0.0044166907,-0.024515491,0.04595407,0.08793297,-