insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8148514','utility','8148514','US','4/3/2012','Disclosed is a novel substance capable of regulating the expression of a telomerase reverse transcriptase gene in a cell of a mammal. A gene capable of regulating the expression of hTERT, comprising a nucleotide sequence depicted in SEQ ID No: 1 or 2. The expression of a telomerase reverse transcriptase gene can be inhibited by inhibiting the expression of the gene. By utilizing this mechanism, the expression of a telomerase reverse transcriptase gene can be regulated.','hTERT gene expression regulatory gene','B2',15,'ipg120403.xml',0,'[-0.030306539,0.03723631,0.029930454,-0.010432489,0.023963206,-0.0013344403,-0.0069155334,0.038507886,0.074160434,-0.0013028096,-0.0036338514,-0.026574505,0.03766595,-0.06817297,-0.013432788,-0.03797832,0.045997836,-0.035186853,0.011740865,0.020676553,0.015045196,-0.053857904,-0.02250915,0.012720632,0.014724209,-0.058802016,-0.07343687,0.042940874,-0.062651165,0.049472593,-0.00910004,-0.028674988,0.041518107,0.032212265,-0.013527052,-0.06121749,0.030652495,0.0055412566,0.048783187,-0.022475088,0.07566728,-0.04823443,0.026403546,0.018264001,-0.039820705,0.0025810297,-0.016390057,0.024326434,0.008084243,0.020821389,0.014157965,0.010106333,-0.009120941,0.013464006,-0.0025085604,0.056720644,0.01788209,0.025847416,-0.0557938,0.049236573,0.010859136,-0.031973723,0.022645615,0.019696118,0.042003933,0.05800575,0.09251762,0.04617127,0.012250771,-0.0007565631,0.030500831,-0.027878126,0.021299528,-0.01096985,-0.05614892,-0.02013332,0.019900016,-0.0055655884,0.010413053,0.026218731,-0.12652382,-0.06333669,-0.07283396,-0.019131212,0.048991904,-0.01215845,-0.0011386952,-0.059272677,0.05680604,-0.0103308,-0.02265132,-0.033644654,0.0150436675,0.016811216,0.019548127,0.036232967,0.015681809,0.084521286,0.0006816884,-0.019842438,0.024285939,0.0027113494,-0.032768395,-