insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8151789','utility','8151789','US','4/10/2012','A method and apparatus for mounting solar panels is provided. Preferably, the apparatus includes a base, a solar panel receiving structure, and a support structure coupling the base to the solar panel receiving structure such that the solar panel receiving structure is at least one of elevated and angled relative to the base. The solar panel receiving structure preferably includes a base member, a first side member coupled to the base member, and a second side member coupled to the base member. Preferably, the first side member and the second side member are slotted so as to slidably receive at least one solar panel between the first side member, the second side member, and the base member.','Solar panel mounting structure','B2',12,'ipg120410.xml',0,'[-0.008584564,-0.011835244,0.01736506,-0.0006565604,-0.012497147,0.049682178,-0.0011078179,-0.052592415,0.01361649,0.008054365,-0.034665827,0.0068940665,0.0494515,-0.018281737,0.035585333,0.058158137,0.053883463,-0.061139077,-0.034353342,-0.05679756,0.03630837,-0.03590624,-0.06531677,0.040552393,0.08738656,-0.094036795,-0.011213886,-0.009742821,-0.04132804,0.05917341,0.029350352,-0.012071408,0.021563854,-0.036335204,0.02031338,-0.022443112,0.028830962,0.04742872,0.012193818,0.02163891,0.07735649,-0.012586693,0.025050007,-0.06769795,-0.017668787,0.045149427,-0.03560331,0.05407844,0.02420043,-0.029651541,0.044523127,0.068401985,-0.020355342,-0.013709437,0.02347371,0.08980384,0.0043393024,0.054233905,-0.042018063,-0.0058571473,0.015851093,-0.018162722,-0.040759817,0.0041428045,-0.09067101,0.00022020578,-0.006680724,0.0028634185,0.030175079,0.004710397,-0.0035381834,-0.0478221,0.07409212,-0.029020768,0.002593228,-0.018182825,0.007886838,-0.012662983,-0.020705895,0.08904533,-0.02557562,-0.024826286,-0.006820522,-0.014166887,-0.06754667,-0.